<?php
header('Content-Type: application/json');require_once __DIR__.'/../config/response.php';require_once __DIR__.'/../config/db.php';require_once __DIR__.'/../config/pagination.php';require_once __DIR__.'/../auth/auth_required.php';require_once __DIR__.'/../auth/role_helper.php';
try{$uid=(int)requireAuth()->id;$c=db();requirePermission($c,$uid,'expenses.view');[$page,$size,$offset]=paginationInput($_GET);$search=trim((string)($_GET['search']??''));$status=strtoupper(trim((string)($_GET['status']??'')));$from=trim((string)($_GET['date_from']??''));$to=trim((string)($_GET['date_to']??''));$where=['e.user_id=?'];$types='i';$args=[$uid];if($search!==''){$where[]="CONCAT_WS(' ',e.title,e.category,e.description,s.name,e.source_document_number) LIKE ?";$types.='s';$args[]='%'.$search.'%';}if($status!==''){$where[]='e.status=?';$types.='s';$args[]=$status;}if($from!==''){$where[]='e.expense_date>=?';$types.='s';$args[]=$from;}if($to!==''){$where[]='e.expense_date<=?';$types.='s';$args[]=$to;}$w=implode(' AND ',$where);$join=' FROM expense_notes e LEFT JOIN suppliers s ON s.id=e.supplier_id AND s.user_id=e.user_id';$q=$c->prepare("SELECT COUNT(*) total,ROUND(COALESCE(SUM(e.amount),0),3) amount $join WHERE $w");$q->bind_param($types,...$args);$q->execute();$agg=$q->get_result()->fetch_assoc();$q->close();$order=paginationSort($_GET,['date'=>'e.expense_date','amount'=>'e.amount','title'=>'e.title','created'=>'e.id'],'date');$q=$c->prepare("SELECT e.*,s.name supplier_name,s.reference supplier_reference $join WHERE $w ORDER BY $order,e.id DESC LIMIT ? OFFSET ?");$qt=$types.'ii';$qa=[...$args,$size,$offset];$q->bind_param($qt,...$qa);$q->execute();$rows=$q->get_result()->fetch_all(MYSQLI_ASSOC);$q->close();$total=(int)$agg['total'];unset($agg['total']);paginatedResponse($rows,$page,$size,$total,$agg);}catch(Throwable $e){jsonResponse(['success'=>false,'message'=>'Could not load expenses.','error_code'=>'EXPENSE_LIST_FAILED'],500);}
